function dynamicContrastScore(peaksA, peaksB) {
  const rmsA = avgRMS(peaksA);
  const rmsB = avgRMS(peaksB);
  const ratio = Math.max(rmsA, rmsB) / Math.max(Math.min(rmsA, rmsB), 0.001);
  return Math.round(Math.min(100, (ratio - 1) * 30));
}

